$ ./my-script.sh -a &quot;lofa&quot; -p &quot;miez&quot;$ ./my-script.sh -arg_1 &quot;lofa&quot; --p_out &quot;miez&quot;$ ./my-script.sh --arg_1 &quot;lofa&quot; -p &quot;miez&quot;

